css:
.stcbl-po-print {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 10px;
    color: #000;
    width: 100%;
    line-height: 1.05;
}

@page {
    size: A4 landscape;
    margin: 8mm;
}

/* HEADER */
.stcbl-header {
    width: 100%;
    margin-bottom: 6px;
    border-bottom: 1px solid #000;
    padding-bottom: 4px;
}

.stcbl-header-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}

.stcbl-header-table td {
    border: none !important;
    vertical-align: middle;
    padding: 0;
}

.logo-col {
    width: 16%;
    text-align: left;
}

.title-col {
    width: 64%;
    text-align: center;
}

.tpn-col {
    width: 20%;
    text-align: right;
    vertical-align: bottom;
}

.stcbl-logo {
    max-height: 58px;
    max-width: 90px;
}

.dzongkha-line {
    font-size: 14px;
    font-weight: 600;
    margin-bottom: 2px;
}

.company-name {
    font-size: 18px;
    font-weight: 500;
    color: #c58a2a;
    margin-bottom: 2px;
}

.company-subtitle {
    font-size: 10px;
    font-weight: 600;
}

.tpn-text {
    font-size: 11px;
    font-weight: 700;
    padding-top: 18px;
}

/* TOP INFO */
.top-info-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin-bottom: 0;
}

.top-info-table td {
    border: 1px solid #000;
    padding: 4px 6px;
    vertical-align: middle;
    font-weight: 700;
    font-size: 10px;
}

.top-label {
    width: 15%;
    text-align: center;
}

.top-value {
    width: 35%;
    text-align: center;
}

.red-text {
    color: red;
}

.main-title {
    text-align: center;
    font-size: 11px;
    font-weight: 700;
    padding: 4px 0;
}

/* MAIN TABLE */
.po-main-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin-top: 0;
}

.po-main-table th,
.po-main-table td {
    border: 1px solid #000;
    padding: 1px 2px;
    text-align: center;
    vertical-align: middle;
    word-wrap: break-word;
    overflow-wrap: break-word;
}

.po-main-table th {
    font-weight: 700;
    font-size: 8px;          /* smaller text */
    line-height: 1.0;        /* tight line spacing */
    color: #4f647d;          /* similar blue-gray tone like screenshot */
    height: 64px;            /* better header height */
    vertical-align: middle;
}

.po-main-table td {
    font-size: 9px;
    line-height: 1.0;
    height: 20px;
}

.text-center {
    text-align: center;
}

.blank-row td {
    height: 20px;
}

.total-row td {
    font-weight: 700;
}

.total-label {
    text-align: center;
}

/* WIDTHS */
.w-model { width: 8%; }
.w-tvo { width: 3.8%; }
.w-port { width: 3.8%; }
.w-kcode { width: 4.2%; }
.w-modelcode { width: 11%; }
.w-pkg { width: 4.8%; }
.w-sfx { width: 4%; }
.w-color { width: 7%; }
.w-ext { width: 3.5%; }
.w-int { width: 3.5%; }
.w-units { width: 4%; }
.w-cfre { width: 7.5%; }
.w-addspec { width: 6.5%; }
.w-specname { width: 7%; }
.w-addopt { width: 4.5%; }
.w-optio { width: 4.5%; }
.w-subtotal { width: 4.5%; }
.w-totalcfre { width: 4.5%; }
.w-final { width: 4.5%; }
.w-customer { width: 5%; }
/* PRINT */
table {
    page-break-inside: avoid;
}

tr {
    page-break-inside: avoid;
    page-break-after: auto;
}

thead {
    display: table-header-group;
}
